import math
# We generate m >= 6 and a t that yields a well-separated floor value.
# The polynomial is (x - 1)^m - 1 = t, i.e., (x - 1)^m = t + 1.
for _ in range(1000):
    m = rng.randint(6, 12)
    t = rng.randint(1000, 5_000_000)
    r = (t + 1)**(1.0 / m)
    if m % 2 == 1:
        P = (t + 2) / (1.0 + r)
    else:
        denom = r * r - 1.0
        if denom <= 0:
            continue
        P = t / denom
    if not math.isfinite(P):
        continue
    if P <= 5:
        continue
    frac = P - math.floor(P)
    if frac < 0.15 or frac > 0.85:
        continue
    if P > 1e12:
        continue
    return {'m': m, 't': t}
# Fallback values known to satisfy constraints in practice
m = 8
t = 123456
return {'m': m, 't': t}

