    return (False, None)
m = assign['m']
t = assign['t']
if not isinstance(m, int) or not isinstance(t, int):
    # Types must be integers
    return (False, None)
if m < 5 or t < 2:
    # Domain restrictions for non-triviality and existence of nonreal roots
    return (False, None)
# Compute product of nonreal roots using the identity:
# (x - 1)^m = t + 1 -> roots are 1 + r * zeta, zeta runs over m-th roots of unity, r = (t+1)^{1/m}.
# Product of all roots: prod_{j}(1 + r zeta_j) = 1 - (-1)^m r^m = 1 - (-1)^m (t+1).
# Real roots: for odd m, only zeta=1 -> value 1+r; for even m, zeta=±1 -> values 1±r.
r = (t + 1)**(1.0 / m)
if m % 2 == 1:
