else:
    denom = r * r - 1.0
    if denom <= 0:
        # Denominator must be positive (r>1), otherwise invalid instance
        return (False, None)
    P = t / denom
if not math.isfinite(P):
    # Numerical stability check
    return (False, None)
if P <= 5:
    # Enforce difficulty: avoid very small answers
    return (False, None)
frac = P - math.floor(P)
if frac < 0.1 or frac > 0.9:
    # Avoid borderline floors that can be guessed or suffer floating error
    return (False, None)
answer = int(math.floor(P))
